+inline bool
+same_scalar(Tensor_attributes::pass_by_values_t const &a, Tensor_attributes::pass_by_values_t const &b) {
+    if (a.index() != b.index()) {
+        return false;
+    }
+    return std::visit(
+        [&](auto const &value) {
+            using T           = std::decay_t<decltype(value)>;
+            auto const &other = std::get<T>(b);
+            return std::memcmp(&value, &other, sizeof(T)) == 0;
+        },
+        a);
