+void
+fill_row(Value_type const& vt, int row_class, uint32_t* words, int64_t extent, uint64_t& rng) {
+    auto const random_position = [&]() {
+        return static_cast<int64_t>(splitmix64(rng) % static_cast<uint64_t>(extent));
+    };
