+std::vector<int32_t>
+vocabulary_iota(int64_t rows) {
+    std::vector<int32_t> iota(static_cast<size_t>(rows * vocabulary));
+    for (size_t i = 0; i < iota.size(); ++i) {
+        iota[i] = static_cast<int32_t>(static_cast<int64_t>(i) % vocabulary);
