+        if (ptr_ != nullptr) {
+            cudaFree(ptr_);
+        }
+    }
+    Device_buffer(Device_buffer const&) = delete;
+    Device_buffer&
+    operator=(Device_buffer const&) = delete;
+    void*
+    get() const {
+        return ptr_;
+    }
+
+   private:
+    void* ptr_ = nullptr;
+};
