+fe::error_t
+build(fe::graph::Graph& graph, cudnnHandle_t handle) {
+    auto status = graph.validate();
+    if (status.is_good()) {
+        status = graph.build_operation_graph(handle);
+    }
+    if (status.is_good()) {
+        status = graph.create_execution_plans({fe::HeurMode_t::A});
