+std::vector<int64_t>
+make_packed_stride(std::vector<int64_t> const& shape) {
+    std::vector<int64_t> stride(shape.size(), 1);
+    for (size_t i = shape.size(); i > 1; --i) {
+        stride[i - 2] = stride[i - 1] * shape[i - 1];
+    }
+    return stride;
