+class InspectableGraph : public fe::graph::Graph {
+   public:
+    fe::error_t
+    expand_for_test() {
+        return expand_subtree();
+    }
+
+    std::shared_ptr<fe::OperationGraph_v8>
+    operation_graph_for_test() const {
